3function Header() {
4  const [query, setQuery] = useState("");
5  const searchRef = useRef(null);
6
7  // Utilize useEffect() to focus on the search
8  useEffect(function () {
9    searchRef.current.focus();
10  }, []);
11
12  return (
13    <header className="header">
14      <h2 className="title-primary">My Daily Journal</h2>
15      <p className="subtitle">Capture your thoughts, one day at a time.</p>
16      <input
17        ref={searchRef}
18        className="search-input"
19        type="text"
20        placeholder="Search entries..."
21        value={query}
22        onChange={(e) => setQuery(e.target.value)}
23      />
24    </header>
25  );
26}
27
28export default Header;

1function Drawer({ entry, onClose }) {
2  if (!entry) return null;
3
4  return (
5    <div className="drawer-overlay">
6      <div className="drawer">
7        <button className="drawer-close" onClick={onClose}>×</button>
8        <h2>{entry.title}</h2>
9        <p className="drawer-meta">{entry.date} · {entry.author}</p>
10        <p className="drawer-content">{entry.content}</p>
11      </div>
12    </div>
13  );
14}
15
16export default Drawer;

